CREATE TABLE public.reversos (
 numero bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 criado_em timestamptz NOT NULL DEFAULT now(),
 solicitante_id uuid NOT NULL REFERENCES public.profiles(id),
 solicitante text NOT NULL,
 perfil_origem text NOT NULL CHECK (perfil_origem IN ('lojinha','sac')),
 status text NOT NULL DEFAULT 'NOVO REVERSO',
 origem_solicitacao text[] NOT NULL CHECK (cardinality(origem_solicitacao) > 0 AND origem_solicitacao <@ ARRAY['Cliente entrou em contato','Identificado internamente']::text[]),
 pax_nome text NOT NULL, cpf text NOT NULL, pax_id text NOT NULL, id_delivery text NOT NULL,
 responsavel text NOT NULL, destino text NOT NULL, ano text NOT NULL,
 autorizacao_mandae text NOT NULL, rastreamento_mandae text NOT NULL,
 motivos text[] NOT NULL CHECK (cardinality(motivos) > 0 AND motivos <@ ARRAY['Troca de tamanho','Defeito']::text[]),
 observacao text, anexos jsonb NOT NULL DEFAULT '[]'::jsonb,
 CONSTRAINT reverso_defeito_anexos CHECK (NOT ('Defeito' = ANY(motivos)) OR jsonb_array_length(anexos) > 0)
);
GRANT SELECT, INSERT ON public.reversos TO authenticated;
GRANT ALL ON public.reversos TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.reversos_numero_seq TO authenticated, service_role;
ALTER TABLE public.reversos ENABLE ROW LEVEL SECURITY;
CREATE POLICY reversos_leitura ON public.reversos FOR SELECT TO authenticated USING (public.meu_status_aprovacao() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'sac') OR public.has_role(auth.uid(),'lojinha')));
CREATE POLICY reversos_criacao ON public.reversos FOR INSERT TO authenticated WITH CHECK (solicitante_id = auth.uid() AND public.meu_status_aprovacao() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),perfil_origem::public.app_role)) AND (public.has_role(auth.uid(),'admin') OR public.tem_permissao(auth.uid(),'chamados') OR public.tem_permissao(auth.uid(),'reenvios')));
CREATE POLICY reversos_anexos_leitura ON storage.objects FOR SELECT TO authenticated USING (bucket_id='reversos-anexos' AND public.meu_status_aprovacao() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'sac') OR public.has_role(auth.uid(),'lojinha')));
CREATE POLICY reversos_anexos_envio ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='reversos-anexos' AND (storage.foldername(name))[1]=auth.uid()::text AND public.meu_status_aprovacao() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'sac') OR public.has_role(auth.uid(),'lojinha')) AND (public.has_role(auth.uid(),'admin') OR public.tem_permissao(auth.uid(),'chamados') OR public.tem_permissao(auth.uid(),'reenvios')));
CREATE POLICY reversos_anexos_limpeza ON storage.objects FOR DELETE TO authenticated USING (bucket_id='reversos-anexos' AND (storage.foldername(name))[1]=auth.uid()::text);